use std::collections::{BTreeMap, BTreeSet};
use std::path::{Path, PathBuf};

use callisto_model::release::is_safe_artifact_component;
use callisto_model::{
    ConfigKey, Ecosystem, GitHubRepository, PackageId, PublishTarget, RegistryKey, ReleaseTrigger, Severity,
    TagTemplate,
};

use crate::changelog::ChangelogLayout;
use crate::config::groups::{GroupTable, RawGroupTable};
use crate::config::pattern::PackagePattern;
use crate::config::raw::{RawConfig, RawProductReleaseConfig};
use crate::error::ConfigError;

#[derive(Clone, Debug)]
pub struct ResolvedConfig {
    pub root: PathBuf,
    pub changesets_dir: PathBuf,
    pub cascade: CascadeConfig,
    pub validation: ValidationConfig,
    pub changelog_layout: ChangelogLayout,
    pub product_release: Option<ProductReleaseConfig>,
    pub registries: BTreeMap<RegistryKey, RegistryConfig>,
    /// Per-package override rules from `[[package]]` blocks, in TOML declaration order. Every rule is
    /// ecosystem-qualified; the first one that applies to a package wins (see `resolve_package_config`).
    pub packages: Vec<(PackageId, PackageConfig)>,
    /// Bulk config-override rules from `[[package-set]]` blocks, in TOML declaration order.
    /// Applied as a fallback when no `[[package]]` rule matches a package.
    /// Unlike `[[package]]` (exact `PackageId` match, first-wins), each
    /// `[[package-set]]` rule uses a glob pattern and can match many packages simultaneously.
    pub package_sets: Vec<(PackagePattern, PackageConfig)>,
    pub groups: GroupTable,
    /// Raw group declarations from `callisto.toml`, kept so that
    /// `Workspace::load` can call `GroupTable::resolve` once the
    /// `IdentityIndex` is available after `ManifestWalkResolver::build`.
    pub(crate) raw_groups: RawGroupTable,
    provenance: BTreeMap<ConfigKey, ConfigProvenance>,
}

/// Credential-free declaration of the one product that owns GitHub binary
/// assets. The operation builder supplies the immutable attestation policy.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ProductReleaseConfig {
    pub package: PackageId,
    pub artifacts: Vec<ProductArtifactConfig>,
    /// The one forge destination; planning requires it.
    pub forge_repository: Option<GitHubRepository>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ConfigProvenance {
    Default,
    Explicit,
}

impl ResolvedConfig {
    pub fn provenance(&self, key: &ConfigKey) -> ConfigProvenance {
        self.provenance.get(key).copied().unwrap_or(ConfigProvenance::Default)
    }

    /// The workspace-relative path to `pre.json`, inside `[changesets] dir`. The single source of truth for this
    /// path: `pre enter`/`pre exit`, `version`'s read and delete, and `apply_version_plan`'s write all resolve it
    /// through this method rather than re-deriving it.
    pub fn pre_json_path(&self) -> PathBuf {
        self.changesets_dir.join("pre.json")
    }

    pub fn rendered_value(&self, key: &ConfigKey) -> Option<String> {
        if key == &ConfigKey::CASCADE_MODE {
            Some(match self.cascade.mode {
                CascadeMode::OutOfRange => "out-of-range".to_string(),
                CascadeMode::Always => "always".to_string(),
            })
        } else if key == &ConfigKey::CASCADE_BUMP_SEVERITY {
            Some(match self.cascade.bump_severity {
                CascadeBumpSeverity::Patch => "patch".to_string(),
                CascadeBumpSeverity::Minor => "minor".to_string(),
            })
        } else if key == &ConfigKey::CASCADE_PEER_ESCALATION {
            Some(self.cascade.peer_escalation.to_string())
        } else if key == &ConfigKey::CASCADE_PRESERVE_NPM_RANGES {
            Some(self.cascade.preserve_npm_ranges.to_string())
        } else if key == &ConfigKey::VALIDATION_ALLOW_EMPTY_CHANGESETS {
            Some(self.validation.allow_empty_changesets.to_string())
        } else {
            None
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct CascadeConfig {
    pub mode: CascadeMode,
    pub bump_severity: CascadeBumpSeverity,
    pub peer_escalation: bool,
    pub preserve_npm_ranges: bool,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CascadeMode {
    OutOfRange,
    Always,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CascadeBumpSeverity {
    Patch,
    Minor,
}

impl CascadeBumpSeverity {
    pub fn as_severity(self) -> Severity {
        match self {
            CascadeBumpSeverity::Patch => Severity::Patch,
            CascadeBumpSeverity::Minor => Severity::Minor,
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ValidationConfig {
    pub allow_empty_changesets: bool,
}

#[derive(Clone, Debug)]
pub struct RegistryConfig {
    pub kind: Ecosystem,
    pub url: Option<String>,
    /// Upload endpoint of a `pypi` registry whose index (`url`) is not also where files are uploaded.
    pub publish_url: Option<String>,
    /// How long a version this run published may take to appear; `None` is the ecosystem's default.
    pub confirm_timeout: Option<std::time::Duration>,
    /// The longest one publish command may run; `None` is the default of 15 minutes.
    pub publish_timeout: Option<std::time::Duration>,
}

/// One declared release artifact. `target` is opaque -- Callisto passes it to
/// whatever builds the bytes and never parses it -- and `asset_name` is the
/// externally stable name the artifact is published under.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ProductArtifactConfig {
    /// The package whose build produces these bytes. Need not be the product.
    pub package: PackageId,
    pub target: String,
    pub asset_name: String,
}

/// Both `product-package` and every `[[release.artifact]] package` must name one
/// ecosystem-qualified identity; one parser so the two cannot drift.
fn parse_qualified_package(value: &str, key: &str) -> Result<PackageId, ConfigError> {
    ConfigError::require_qualified(value, key)?;
    PackageId::parse(value).map_err(|_error| ConfigError::InvalidProductRelease {
        detail: format!("{key} must be an ecosystem-qualified package identity"),
    })
}

fn resolve_product_release(raw: RawProductReleaseConfig) -> Result<ProductReleaseConfig, ConfigError> {
    let package = parse_qualified_package(&raw.product_package, "product-package")?;
    if raw.artifact.is_empty() {
        return Err(ConfigError::InvalidProductRelease {
            detail: "a [release] section must declare at least one [[release.artifact]]".to_owned(),
        });
    }
    let mut artifacts = Vec::with_capacity(raw.artifact.len());
    let mut seen_assets = BTreeSet::new();
    for entry in &raw.artifact {
        let package = parse_qualified_package(&entry.package, "[[release.artifact]] package")?;
        if !is_safe_artifact_component(&entry.target) || !is_safe_artifact_component(&entry.asset_name) {
            return Err(ConfigError::InvalidProductRelease {
                detail: format!(
                    "artifact target `{}` and asset-name `{}` must each be a single safe path component",
                    entry.target, entry.asset_name
                ),
            });
        }
        if !seen_assets.insert(entry.asset_name.clone()) {
            return Err(ConfigError::InvalidProductRelease {
                detail: format!("asset-name `{}` is declared more than once", entry.asset_name),
            });
        }
        artifacts.push(ProductArtifactConfig {
            package,
            target: entry.target.clone(),
            asset_name: entry.asset_name.clone(),
        });
    }
    let forge_repository = raw
        .forge_repository
        .clone()
        .map(|raw| {
            GitHubRepository::parse(&raw).map_err(|error| ConfigError::InvalidProductRelease {
                detail: format!("forge-repository `{raw}` is invalid: {error}"),
            })
        })
        .transpose()?;
    Ok(ProductReleaseConfig {
        package,
        artifacts,
        forge_repository,

        forge_repository,
    })
}

/// Per-package overrides from a `[[package]]` block in `callisto.toml`.
///
/// Every field is `Option<T>` — `None` means "not specified; use the package's default."
/// Only fields that the user explicitly set in the `[[package]]` block are `Some`.
#[derive(Clone, Debug)]
pub struct PackageConfig {
    pub release_trigger: Option<ReleaseTrigger>,
    pub publish_to: Option<Vec<PublishTarget>>,
    pub tag_template: Option<TagTemplate>,
    /// Consulted for the last tag only after `tag_template` finds none.
    pub previous_tag_templates: Vec<TagTemplate>,
    /// Changelog path relative to the package's own root directory.
    pub changelog: Option<PathBuf>,
    pub pre_major_inference: Option<PreMajorInferencePolicy>,
}

/// Pre-1.0 (`0.y.z`) severity-downgrade policy. A closed 3-state choice --
/// modeled as an enum rather than two independent bools so the type system
/// rules out the unreachable-via-parser 4th combination a `{breaking_to_minor:
/// false, feat_to_patch: true}`-shaped struct literal could otherwise
/// construct.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum PreMajorInferencePolicy {
    #[default]
    Off,
    /// Downgrades an inferred Major bump to Minor.
    Conservative,
    /// Downgrades an inferred Major bump to Minor, and Minor to Patch.
    ConservativeFeat,
}

pub fn parse_publish_target(s: &str) -> Option<PublishTarget> {
    match s {
        "crates-io" => Some(PublishTarget::CratesIo),
        "npm" => Some(PublishTarget::Npm {
            registry: None,
            access: None,
        }),
        "pypi" => Some(PublishTarget::Pypi { index: None }),
        "nuget" => Some(PublishTarget::NuGet { source: None }),
        "github-release" => Some(PublishTarget::GitHubRelease),
        "none" => Some(PublishTarget::None),
        _ => None,
    }
}

pub fn parse_release_trigger(s: &str) -> Option<ReleaseTrigger> {
    match s {
        "changeset" => Some(ReleaseTrigger::Changeset),
        "auto" => Some(ReleaseTrigger::Auto),
        _ => None,
    }
}

/// A `[[package]]` rule applies to a package when it has a manifest in the rule's ecosystem whose own name is the
/// rule's name.
///
/// `native_names` is the package's name in each ecosystem it has a manifest in. A dual package's names can differ per
/// ecosystem, so `npm/michi-node` does not apply to the package whose npm name is `@orin-dx/michi`, whatever its
/// directory or Cargo name is, which is the same identity a `[[fixed-group]]` member must give.
pub(crate) fn rule_applies(rule_id: &PackageId, native_names: &[(Ecosystem, &str)]) -> bool {
    rule_id.ecosystem().is_some_and(|eco| {
        native_names
            .iter()
            .any(|(ecosystem, name)| *ecosystem == eco && *name == rule_id.name())
    })
}

/// The first `[[package]]` rule, in TOML declaration order, that applies to `id`; `None` if none does.
///
/// MUST NOT sort or partition `cfg.packages`: declaration order is the specificity.
pub(crate) fn resolve_package_config<'a>(
    native_names: &[(Ecosystem, &str)],
    cfg: &'a ResolvedConfig,
) -> Option<&'a PackageConfig> {
    cfg.packages
        .iter()
        .find(|(rule_id, _)| rule_applies(rule_id, native_names))
        .map(|(_, pcfg)| pcfg)
}

pub fn parse_pre_major_policy(s: &str) -> Result<PreMajorInferencePolicy, ConfigError> {
    match s {
        "off" => Ok(PreMajorInferencePolicy::Off),
        "conservative" => Ok(PreMajorInferencePolicy::Conservative),
        "conservative-feat" => Ok(PreMajorInferencePolicy::ConservativeFeat),
        _ => Err(ConfigError::InvalidPreMajorInference { found: s.to_string() }),
    }
}

/// Parses the five override fields shared by `[[package]]` and
/// `[[package-set]]` blocks (release-trigger, tag-template, changelog,
/// pre-major-inference, publish-to) into a `PackageConfig`.
///
/// `previous_tag_templates` is `[[package]]`-only; `[[package-set]]` callers pass `None`.
#[allow(clippy::too_many_arguments)]
fn parse_package_config_fields(
    callisto_toml: &Path,
    error_prefix: &str,
    pattern_display: &str,
    release_trigger: Option<&str>,
    tag_template: Option<&str>,
    previous_tag_templates: Option<&[String]>,
    changelog: Option<&str>,
    pre_major_inference: Option<&str>,
    publish_to: Option<&[String]>,
) -> Result<PackageConfig, ConfigError> {
    let release_trigger = release_trigger
        .map(|value| {
            parse_release_trigger(value).ok_or_else(|| ConfigError::InvalidReleaseTrigger {
                path: callisto_toml.to_path_buf(),
                location: format!("{error_prefix} release-trigger"),
                value: value.to_owned(),
            })
        })
        .transpose()?;

    let tag_template = tag_template
        .map(TagTemplate::parse)
        .transpose()
        .map_err(ConfigError::Tag)?;

    let previous_tag_templates = previous_tag_templates
        .unwrap_or_default()
        .iter()
        .map(|template| TagTemplate::parse(template))
        .collect::<Result<Vec<_>, _>>()
        .map_err(ConfigError::Tag)?;

    let changelog = changelog
        .map(|s| {
            callisto_model::workspace_relative(s).map_err(|_err| ConfigError::InvalidChangelogPath {
                pattern: pattern_display.to_string(),
                value: s.to_string(),
            })
        })
        .transpose()?;

    let pre_major_inference = pre_major_inference.map(parse_pre_major_policy).transpose()?;

    let publish_to = publish_to
        .map(|targets| {
            targets
                .iter()
                .map(|value| {
                    parse_publish_target(value).ok_or_else(|| ConfigError::InvalidPublishTarget {
                        path: callisto_toml.to_path_buf(),
                        location: format!("{error_prefix} publish-to"),
                        value: value.clone(),
                    })
                })
                .collect::<Result<Vec<_>, _>>()
        })
        .transpose()?;

    Ok(PackageConfig {
        release_trigger,
        publish_to,
        tag_template,
        previous_tag_templates,
        changelog,
        pre_major_inference,
    })
}

/// Reads and parses `root/callisto.toml` (absent means empty), then [`resolve`]s it.
pub fn load(root: &Path) -> Result<ResolvedConfig, ConfigError> {
    let callisto_toml = root.join("callisto.toml");
    let content = callisto_model::strict_fs::read_optional(&callisto_toml).map_err(|e| ConfigError::Read {
        path: callisto_toml.clone(),
        message: e.to_string(),
    })?;
    let raw = if let Some(content) = content {
        parse_raw(&callisto_toml, &content)?
    } else {
        RawConfig::default()
    };
    resolve(root, raw)
}

/// Parses `callisto.toml` text, telling a syntax error from an unknown key and from a misfit value.
pub fn parse_raw(path: &Path, text: &str) -> Result<RawConfig, ConfigError> {
    let error = match toml::from_str::<RawConfig>(text) {
        Ok(raw) => return Ok(raw),
        Err(error) => error,
    };
    let (path, message) = (path.to_path_buf(), error.to_string());
    Err(if toml::from_str::<toml::Table>(text).is_err() {
        ConfigError::ParseToml { path, message }
    } else if error.message().starts_with("unknown field") {
        ConfigError::UnknownField { path, message }
    } else {
        ConfigError::InvalidValue { path, message }
    })
}

